import Distributions: mgf, NegativeBinomial
import JSON

"""
	gen( t, r, p, name )

Generate fixture data and write to file.

# Arguments

* `t`: input value
* `r`: number of successes until experiment is stopped
* `p`: success probability
* `name::AbstractString`: output filename

# Examples

``` julia
julia> p = rand( 1000 );
julia> t = ( rand( 1000 ) .- 1.0 ) .* -log1p.( -p );
julia> r = ( rand( 1000 ) .* 20 ) .+ 0.5;
julia> gen( t, r, p, "data.json" );
```
"""
function gen( t, r, p, name )
	z = Array{Float64}( undef, length(t) );
	for i in eachindex(t)
		z[ i ] = mgf( NegativeBinomial( r[i], p[i] ), t[i] );
	end

	# Store data to be written to file as a collection:
	data = Dict([
		("t", t),
		("r", r),
		("p", p),
		("expected", z)
	]);

	# Based on the script directory, create an output filepath:
	filepath = joinpath( dir, name );

	# Write the data to the output filepath as JSON:
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# Generate fixtures (`t` must be less than `-ln(1-p)`):
p = rand( 1000 );
t = ( ( rand( 1000 ) .* 1.5 ) .- 1.0 ) .* -log1p.( -p );
r = ( rand( 1000 ) .* 20 ) .+ 0.5;
gen( t, r, p, "data.json" );
